\text {Let } w &= 2x^3 \\
w &= 2(x^2-3x+2) \cdot p + r
\end{align*}
So, when we substitute $w$ into the equation, we get:
\begin{align*}
w &= 2(x^2-3x+2) \cdot p + r \\
2x^3 &= 2(x^2-3x+2) \cdot p + r \\
(x^2-3x+2)\cdot p  &=  x^3 - r \\
 \text{Multiplying both sides by } \frac{1}{2}: \quad
(x^2-3x+2) \cdot p  &=  \frac{1}{2}(x^3 - r) \\
p &= \frac{x^3 - r}{2(x^2 - 3x + 2)} \\
\text{Since }p,r \text{ are integers, } (x^3-r)\text{ must be even number, so we only consider } x = 1 \text{: } \\
\text{let } x &= 1,  \quad r &= x^3 - 2(x^2-3x+2)\cdot p \\
r &= 1^3 - 2(1^2 - 3(1) + 2)\cdot p \\
r &= 1-2p
\end{align*}
To finish the problem, we need to find $p$.
\begin{align*}
p &= \frac{1}{2(1^2 - 3(1) + 2)} \\
&= \frac{1}{2(1-3+2)} \\
&= \frac{1}{2\cdot 2} \\
&= \frac{1}{4}
\end{align*}
So, now we can find $r$:
\begin{align*}
r &= 1- 2 \cdot \frac{1}{4} \\
&= 1 - \frac{1}{2} \\
&= \boxed \frac{1}{2}
\end{align*}
The final remainder of dividing $x^4 - 3x^3 + 4x^2 + 11x - 9$ by $(x^2 - 3x + 2)$ is \boxed{\frac{1}{2}}.

\end{document}
```

